\operatorname{dia}(\operatorname{in}(c,s),A)[q:=r]_{\mathsf F}
=
\begin{cases}
\operatorname{dia}(\operatorname{in}(c,s),A),&s=q,\\
\operatorname{dia}(\operatorname{in}(c,s),A[q:=r]_{\mathsf F}),&s\ne q,\ s\ne r,\\
\operatorname{dia}(\operatorname{in}(c,t),(A[s:=t]_{\mathsf F})[q:=r]_{\mathsf F}),&s\ne q,\ s=r,
\end{cases}
